def link_existing_records(apps, schema_editor):
    """Asocia las recetas y los reportes existentes al tratamiento al que pertenecían.

    La consulta crea la receta y el plan en la misma transacción, con el mismo medicamento.
    Un reporte pertenece al tratamiento que estaba vigente cuando se envió.
    """
    TreatmentPlan = apps.get_model('medical_monitor', 'TreatmentPlan')
    Prescription = apps.get_model('medical_monitor', 'Prescription')
    PatientReport = apps.get_model('medical_monitor', 'PatientReport')
    plans_by_patient = {}
    for plan in TreatmentPlan.objects.order_by('created_at', 'id'):
        plans_by_patient.setdefault(plan.patient_id, []).append(plan)

    for prescription in Prescription.objects.filter(treatment_plan__isnull=True):
        for plan in plans_by_patient.get(prescription.patient_id, []):
            same_medication = prescription.medication_name in (plan.medication_name, plan.title)
            if same_medication and abs(plan.created_at - prescription.created_at) <= timedelta(minutes=1):
                Prescription.objects.filter(pk=prescription.pk).update(treatment_plan=plan)
                break

    for report in PatientReport.objects.filter(treatment_plan__isnull=True):
        # El más reciente que ya existía y que no se había cerrado antes del reporte.
        candidates = [
            plan for plan in plans_by_patient.get(report.patient_id, [])
            if plan.created_at <= report.created_at and (plan.is_active or plan.updated_at >= report.created_at)
        ]
        if candidates:
            PatientReport.objects.filter(pk=report.pk).update(treatment_plan=candidates[-1])


